values
  ('arwa-al-sulayhi', 'الملكة أروى بنت أحمد الصليحي', 'ملكة يمنية حكمت الدولة الصليحية', 'السياسة والحكم', 'YE11', 'إب', 'تاريخية', 1048, 1138, 'من أبرز حاكمات اليمن في العصور الوسطى، واتخذت من جبلة مركزًا للحكم والعلم والعمران.', null, null, null, null, null, null, 1, true),
  ('ali-al-sulayhi', 'علي بن محمد الصليحي', 'مؤسس الدولة الصليحية', 'السياسة والحكم', 'YE23', 'صنعاء', 'تاريخية', null, 1067, 'قائد يمني أسس الدولة الصليحية في القرن 11 ووحّد أجزاء واسعة من اليمن.', null, null, null, null, null, null, 2, true),
  ('asma-bint-shihab', 'أسماء بنت شهاب', 'ملكة يمنية من الدولة الصليحية', 'السياسة والحكم', 'YE23', 'صنعاء', 'تاريخية', null, 1087, 'شخصية سياسية بارزة شاركت في إدارة الدولة الصليحية وعُرفت بحضورها في شؤون الحكم.', null, null, null, null, null, null, 3, true),
  ('al-hamdani', 'الحسن بن أحمد الهمداني', 'جغرافي ومؤرخ ولغوي يمني', 'العلم والتعليم', 'YE13', 'أمانة العاصمة', 'تاريخية', 893, 945, 'عالم موسوعي من صنعاء، ومن أشهر آثاره كتابا صفة جزيرة العرب والإكليل.', null, null, null, null, null, null, 4, true),
  ('nashwan-al-himyari', 'نشوان بن سعيد الحميري', 'عالم وشاعر ولغوي يمني', 'الأدب والشعر', 'YE29', 'عمران', 'تاريخية', null, 1178, 'عالم يمني ارتبط اسمه باللغة والشعر والتاريخ، وله مؤلفات بارزة في التراث العربي.', null, null, null, null, null, null, 5, true),
  ('al-shawkani', 'محمد بن علي الشوكاني', 'فقيه وقاضٍ ومؤلف يمني', 'العلم والتعليم', 'YE13', 'أمانة العاصمة', 'تاريخية', 1759, 1834, 'عالم يمني من صنعاء ترك مؤلفات مؤثرة في الفقه والحديث والتفسير.', null, null, null, null, null, null, 6, true),
  ('wahb-ibn-munabbih', 'وهب بن منبه', 'مؤرخ وراوية يمني', 'العلم والتعليم', 'YE20', 'ذمار', 'تاريخية', 654, 732, 'من رواة الأخبار الأوائل، وارتبطت سيرته بالمعرفة والتاريخ في اليمن خلال العصر الأموي.', null, null, null, null, null, null, 7, true),
  ('abd-al-razzaq-al-sannani', 'عبد الرزاق الصنعاني', 'محدّث ومصنف يمني', 'العلم والتعليم', 'YE13', 'أمانة العاصمة', 'تاريخية', 744, 827, 'عالم حديث من صنعاء وصاحب المصنف، أحد المصادر المبكرة في التراث الإسلامي.', null, null, null, null, null, null, 8, true),
  ('sayf-ibn-dhi-yazan', 'سيف بن ذي يزن', 'ملك يمني من العصر الحميري', 'السياسة والحكم', 'YE13', 'أمانة العاصمة', 'تاريخية', null, 578, 'ملك يمني ارتبط اسمه بمقاومة النفوذ الحبشي واستعادة الحكم المحلي في اليمن.', null, null, null, null, null, null, 9, true),
  ('dhu-nuwas', 'ذو نواس', 'آخر ملوك حمير', 'السياسة والحكم', 'YE11', 'إب', 'تاريخية', null, 525, 'ملك حميري ارتبطت سيرته بمدينة ظفار التاريخية وبالمرحلة الأخيرة من دولة حمير.', null, null, null, null, null, null, 10, true),
  ('karib-il-watar', 'كرب إل وتر', 'ملك سبئي بارز', 'السياسة والحكم', 'YE26', 'مأرب', 'تاريخية', null, null, 'من أبرز ملوك سبأ، ارتبط اسمه بتوسّع الدولة السبئية وبنقوش تاريخية مهمة في مأرب.', null, null, null, null, null, null, 11, true),
  ('shammar-yuharish', 'شمر يهرعش', 'ملك حميري وحّد ممالك يمنية قديمة', 'السياسة والحكم', 'YE11', 'إب', 'تاريخية', null, null, 'ملك من ملوك حمير ارتبط اسمه بتوحيد سبأ وذي ريدان وحضرموت في كيان سياسي واحد.', null, null, null, null, null, null, 12, true),
  ('queen-bilqis', 'الملكة بلقيس', 'شخصية تراثية مرتبطة بمملكة سبأ', 'التراث والتاريخ', 'YE26', 'مأرب', 'تاريخية', null, null, 'شخصية حاضرة في الذاكرة اليمنية والعربية، وترتبط في الموروث التاريخي بمملكة سبأ ومأرب.', null, null, null, null, null, null, 13, true),
  ('waddah-al-yaman', 'وضاح اليمن', 'شاعر يمني من العصر الأموي', 'الأدب والشعر', 'YE13', 'أمانة العاصمة', 'تاريخية', null, 708, 'شاعر عربي يمني اشتهر بالشعر الغزلي وظل اسمه حاضرًا في الذاكرة الأدبية.', null, null, null, null, null, null, 14, true),
  ('yahya-al-rassi', 'يحيى بن الحسين الرسي', 'مؤسس الدولة الزيدية في اليمن', 'السياسة والحكم', 'YE22', 'صعدة', 'تاريخية', 859, 911, 'إمام وفقيه أسس الدولة الزيدية في صعدة أواخر القرن 9.', null, null, null, null, null, null, 15, true),
  ('ahmed-ibn-alwan', 'أحمد بن علوان', 'شاعر ومتصوف يمني', 'الأدب والشعر', 'YE15', 'تعز', 'تاريخية', null, 1267, 'أديب ومتصوف يمني ارتبطت سيرته بمنطقة يفرس في تعز وله تراث شعري وفكري معروف.', null, null, null, null, null, null, 16, true),
  ('ibn-al-dayba', 'عبد الرحمن بن علي الديبع', 'مؤرخ وفقيه يمني', 'التراث والتاريخ', 'YE18', 'الحديدة', 'تاريخية', 1461, 1537, 'مؤرخ من زبيد ألّف في تاريخ اليمن وترك أعمالًا مهمة في السيرة والحديث.', null, null, null, null, null, null, 17, true),
  ('muhammad-al-zubayri', 'محمد محمود الزبيري', 'شاعر وسياسي وثائر يمني', 'الأدب والشعر', 'YE13', 'أمانة العاصمة', 'تاريخية', null, 1965, 'من أبرز شعراء الحركة الوطنية اليمنية وأحد رموز النضال الجمهوري.', null, null, null, null, null, null, 18, true),
  ('abdullah-al-sallal', 'عبد الله السلال', 'أول رئيس للجمهورية العربية اليمنية', 'السياسة والحكم', 'YE13', 'أمانة العاصمة', 'تاريخية', 1917, 1994, 'ضابط وسياسي يمني قاد ثورة 26 سبتمبر وأصبح أول رئيس للجمهورية العربية اليمنية.', null, null, null, null, null, null, 19, true),
  ('ibrahim-al-hamdi', 'إبراهيم الحمدي', 'رئيس الجمهورية العربية اليمنية بين 1974 و1977', 'السياسة والحكم', 'YE30', 'الضالع', 'تاريخية', 1943, 1977, 'رئيس يمني ارتبط اسمه بمشروع بناء الدولة وتطوير الإدارة وتعزيز حضور المؤسسات.', null, null, null, null, null, null, 20, true),
  ('q58297', 'أبو بكر القربي', 'سياسي يمني', 'العلم والتعليم', 'YE14', 'البيضاء', 'معاصرة', 1942, null, 'سياسي يمني. شخصية يمنية مرتبطة بمحافظة البيضاء، ويعرض الدليل مجال حضورها وأبرز ما عُرفت به.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Abu%20Bakr%20alQirbi%20%28cropped%29.jpg', null, null, null, null, null, 21, true),
  ('q26205352', 'داود الحدابي', 'باحث يمني ومحاضر دولي في علوم الإدارة', 'العلم والتعليم', 'YE13', 'أمانة العاصمة', 'معاصرة', 1955, null, 'باحث يمني ومحاضر دولي في علوم الإدارة. شخصية يمنية مرتبطة بمحافظة أمانة العاصمة، ويعرض الدليل مجال حضورها وأبرز ما عُرفت به.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Dawod.jpg', null, null, null, null, null, 22, true),
  ('q12189231', 'عبد الرحمن باعباد', 'داعية إسلامي يمني', 'العلم والتعليم', 'YE19', 'حضرموت', 'تاريخية', 1973, 2018, 'داعية إسلامي يمني. شخصية يمنية مرتبطة بمحافظة حضرموت، ويعرض الدليل مجال حضورها وأبرز ما عُرفت به.', 'https://commons.wikimedia.org/wiki/Special:FilePath/%D8%A7%D9%84%D8%B4%D9%8A%D8%AE%20%D8%B9%D8%A8%D8%AF%D8%A7%D9%84%D8%B1%D8%AD%D9%85%D9%86%20%D8%A8%D8%A7%D8%B9%D8%A8%D8%A7%D8%AF.jpg', null, null, null, null, null, 23, true),
