  ('q4678423', 'عمر بن حفيظ', 'داعية إسلامي ومدرس يمني', 'العلم والتعليم', 'YE19', 'حضرموت', 'معاصرة', 1963, null, 'داعية إسلامي ومدرس يمني. شخصية يمنية مرتبطة بمحافظة حضرموت، ويعرض الدليل مجال حضورها وأبرز ما عُرفت به.', 'https://commons.wikimedia.org/wiki/Special:FilePath/Habib%20Umar%20bin%20Hafidz%2C%20Nabawi%20TV%2C%2008.44.jpg', null, null, null, null, null, 25, true),
  ('q99300071', 'يحيى بن حسين الديلمي', 'من مراجع الزيدية المعاصرين في اليمن', 'العلم والتعليم', 'YE13', 'أمانة العاصمة', 'معاصرة', 1961, null, 'من مراجع الزيدية المعاصرين في اليمن. شخصية يمنية مرتبطة بمحافظة أمانة العاصمة، ويعرض الدليل مجال حضورها وأبرز ما عُرفت به.', 'https://commons.wikimedia.org/wiki/Special:FilePath/%D8%A7%D9%84%D8%B3%D9%8A%D8%AF%20%D8%A7%D9%84%D8%B9%D9%84%D8%A7%D9%85%D8%A9%20%D9%8A%D8%AD%D9%8A%D9%89%20%D8%A7%D9%84%D8%AF%D9%8A%D9%84%D9%85%D9%8A%20.jpg', null, null, null, null, null, 26, true),
